
-- Fix logo URL in Welcome template
UPDATE public.email_templates 
SET html_content = '<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#f4f4f4;font-family:Arial,Helvetica,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f4f4;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.08);"><tr><td style="background:linear-gradient(135deg,#3A00E5 0%,#6B3AFF 100%);padding:40px 40px 30px;text-align:center;"><img src="https://ellosuit-connect-vista.lovable.app/images/ellosuit-logo.png" alt="Ellosuit" width="180" style="display:inline-block;max-width:180px;height:auto;filter:brightness(0) invert(1);"></td></tr><tr><td style="padding:40px;"><h1 style="color:#1a1a1a;font-size:28px;margin:0 0 16px;text-align:center;">Bem-vindo(a) ao Ellosuit!</h1><p style="color:#4a4a4a;font-size:16px;line-height:1.7;margin:0 0 20px;">Ola <strong>{{nome_cliente}}</strong>,</p><p style="color:#4a4a4a;font-size:16px;line-height:1.7;margin:0 0 20px;">Estamos muito felizes em ter voce conosco! Sua conta foi criada com sucesso e agora voce tem acesso a todas as ferramentas do Ellosuit para transformar a gestao do seu negocio.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f8f7ff;border-radius:8px;margin:24px 0;"><tr><td style="padding:24px;"><h3 style="color:#3A00E5;font-size:18px;margin:0 0 16px;">Primeiros passos:</h3><ul style="color:#4a4a4a;font-size:15px;line-height:2;margin:0;padding-left:20px;"><li>Configure seu perfil e dados da empresa</li><li>Conecte seu WhatsApp para atendimento</li><li>Importe seus contatos e clientes</li><li>Explore os modulos Omni, Flow, Track e Suite</li></ul></td></tr></table><p style="text-align:center;margin:32px 0;"><a href="https://www.ellosuit.online/dashboard" style="display:inline-block;background:linear-gradient(135deg,#3A00E5,#6B3AFF);color:#ffffff;text-decoration:none;padding:16px 40px;border-radius:8px;font-size:16px;font-weight:600;">Acessar Meu Dashboard</a></p><p style="color:#4a4a4a;font-size:16px;line-height:1.7;margin:0;">Precisa de ajuda? Responda este email ou acesse nossa central de suporte. Estamos aqui para voce!</p></td></tr><tr><td style="background-color:#f9f9f9;padding:24px 40px;text-align:center;border-top:1px solid #eee;"><p style="color:#888;font-size:12px;margin:0;">2025 Ellosuit. Todos os direitos reservados.</p><p style="color:#888;font-size:12px;margin:8px 0 0;">Este email foi enviado por contato@ellosuit.com</p></td></tr></table></td></tr></table></body></html>'
WHERE id = '0694ac25-4442-49d0-892b-be075943cf25';

