lor:#16a34a;font-size:18px;text-align:right;font-weight:700;">{{valor_fatura}}</td></tr><tr><td style="padding:8px 0;color:#666;font-size:14px;">Metodo</td><td style="padding:8px 0;color:#1a1a1a;font-size:14px;text-align:right;">{{metodo_pagamento}}</td></tr><tr><td style="padding:8px 0;color:#666;font-size:14px;">ID Transacao</td><td style="padding:8px 0;color:#1a1a1a;font-size:14px;text-align:right;font-family:monospace;">{{id_transacao}}</td></tr><tr><td style="padding:8px 0;color:#666;font-size:14px;">Data Pagamento</td><td style="padding:8px 0;color:#1a1a1a;font-size:14px;text-align:right;">{{data_pagamento}}</td></tr><tr><td style="padding:8px 0;color:#666;font-size:14px;border-top:1px solid #e5e7eb;">Proxima Cobranca</td><td style="padding:8px 0;color:#1a1a1a;font-size:14px;text-align:right;border-top:1px solid #e5e7eb;">{{proxima_cobranca}}</td></tr></table></td></tr></table><p style="text-align:center;margin:32px 0;"><a href="https://www.ellosuit.online/dashboard/assinatura" style="display:inline-block;background:linear-gradient(135deg,#3A00E5,#6B3AFF);color:#ffffff;text-decoration:none;padding:16px 40px;border-radius:8px;font-size:16px;font-weight:600;">Ver Minha Assinatura</a></p></td></tr><tr><td style="background-color:#f9f9f9;padding:24px 40px;text-align:center;border-top:1px solid #eee;"><p style="color:#888;font-size:12px;margin:0;">2025 Ellosuit. Todos os direitos reservados.</p><p style="color:#888;font-size:12px;margin:8px 0 0;">Este email foi enviado por contato@ellosuit.com</p></td></tr></table></td></tr></table></body></html>'
