-- Fix Payment Pending template
UPDATE public.email_templates 
SET html_content = '<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#f4f4f4;font-family:Arial,Helvetica,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f4f4;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.08);"><tr><td style="background:linear-gradient(135deg,#dc2626 0%,#ef4444 100%);padding:40px 40px 30px;text-align:center;"><img src="https://ellosuit-connect-vista.lovable.app/images/ellosuit-logo.png" alt="Ellosuit" width="180" style="display:inline-block;max-width:180px;height:auto;filter:brightness(0) invert(1);"></td></tr><tr><td style="padding:40px;"><h1 style="color:#1a1a1a;font-size:28px;margin:0 0 16px;text-align:center;">Pagamento Pendente</h1><p style="color:#4a4a4a;font-size:16px;line-height:1.7;margin:0 0 20px;">Ola <strong>{{nome_cliente}}</strong>,</p><p style="color:#4a4a4a;font-size:16px;line-height:1.7;margin:0 0 20px;">Identificamos que o pagamento da sua assinatura Ellosuit ainda nao foi processado. Para evitar a interrupcao dos seus servicos, por favor regularize o pagamento.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#fef2f2;border:1px solid #fecaca;border-radius:8px;margin:24px 0;"><tr><td style="padding:24px;"><table width="100%" cellpadding="0" cellspacing="0"><tr><td style="padding:8px 0;color:#666;font-size:14px;">Plano</td><td style="padding:8px 0;color:#1a1a1a;font-size:14px;text-align:right;">{{nome_plano}}</td></tr><tr><td style="padding:8px 0;color:#666;font-size:14px;">Valor</td><td style="padding:8px 0;color:#dc2626;font-size:18px;text-align:right;font-weight:700;">{{valor_fatura}}</td></tr><tr><td style="padding:8px 0;color:#666;font-size:14px;">Vencimento</td><td style="padding:8px 0;color:#1a1a1a;font-size:14px;text-align:right;">{{data_vencimento}}</td></tr></table></td></tr></table><p style="text-align:center;margin:32px 0;"><a href="https://www.ellosuit.online/dashboard/assinatura" style="display:inline-block;background:linear-gradient(135deg,#dc2626,#ef4444);color:#ffffff;text-decoration:none;padding:16px 40px;border-radius:8px;font-size:16px;font-weight:600;">Regularizar Pagamento</a></p><p style="color:#888;font-size:13px;line-height:1.6;margin:20px 0 0;">Se voce ja realizou o pagamento, por favor desconsidere este email. O processamento pode levar ate 48 horas uteis.</p></td></tr><tr><td style="background-color:#f9f9f9;padding:24px 40px;text-align:center;border-top:1px solid #eee;"><p style="color:#888;font-size:12px;margin:0;">2025 Ellosuit. Todos os direitos reservados.</p><p style="color:#888;font-size:12px;margin:8px 0 0;">Este email foi enviado por contato@ellosuit.com</p></td></tr></table></td></tr></table></body></html>'
WHERE id = '1eaf80c7-f806-49f0-aa05-c41c9169ea66';

-- Create Trial Started template
INSERT INTO public.email_templates (id, name, description, category, html_content, is_active, user_id, company_id) VALUES
('a1b2c3d4-0001-4000-8000-000000000001', 'Periodo de Teste Iniciado', 'Email enviado quando o trial comeca', 'onboarding',
'<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#f4f4f4;font-family:Arial,Helvetica,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f4f4;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.08);"><tr><td style="background:linear-gradient(135deg,#3A00E5 0%,#6B3AFF 100%);padding:40px 40px 30px;text-align:center;"><img src="https://ellosuit-connect-vista.lovable.app/images/ellosuit-logo.png" alt="Ellosuit" width="180" style="display:inline-block;max-width:180px;height:auto;filter:brightness(0) invert(1);"></td></tr><tr><td style="padding:40px;"><h1 style="color:#1a1a1a;font-size:28px;margin:0 0 16px;text-align:center;">Seu Periodo de Teste Comecou!</h1><p style="color:#4a4a4a;font-size:16px;line-height:1.7;margin:0 0 20px;">Ola <strong>{{nome_cliente}}</strong>,</p><p style="color:#4a4a4a;font-size:16px;line-height:1.7;margin:0 0 20px;">Voce ativou o periodo de teste do plano <strong>{{nome_plano}}</strong>. Aproveite todos os recursos por 7 dias sem compromisso!</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f8f7ff;border-radius:8px;margin:24px 0;"><tr><td style="padding:24px;"><h3 style="color:#3A00E5;font-size:18px;margin:0 0 16px;">O que esta incluso:</h3><ul style="color:#4a4a4a;font-size:15px;line-height:2;margin:0;padding-left:20px;"><li>Acesso completo a todos os modulos</li><li>Envio de emails e WhatsApp</li><li>Agendamentos e reunioes</li><li>Rastreamento de documentos</li></ul></td></tr></table><p style="text-align:center;margin:32px 0;"><a href="https://www.ellosuit.online/dashboard" style="display:inline-block;background:linear-gradient(135deg,#3A00E5,#6B3AFF);color:#ffffff;text-decoration:none;padding:16px 40px;border-radius:8px;font-size:16px;font-weight:600;">Comecar a Usar</a></p></td></tr><tr><td style="background-color:#f9f9f9;padding:24px 40px;text-align:center;border-top:1px solid #eee;"><p style="color:#888;font-size:12px;margin:0;">2025 Ellosuit. Todos os direitos reservados.</p></td></tr></table></td></tr></table></body></html>',
true, 'c63ba931-0c34-4461-ae8d-2908aed7dd20', '60008c43-e536-482d-a090-91904de57534');

-- Create Trial Ending template
INSERT INTO public.email_templates (id, name, description, category, html_content, is_active, user_id, company_id) VALUES
('a1b2c3d4-0002-4000-8000-000000000002', 'Periodo de Teste Acabando', 'Email enviado 2 dias antes do trial acabar', 'onboarding',
'<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#f4f4f4;font-family:Arial,Helvetica,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f4f4;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.08);"><tr><td style="background:linear-gradient(135deg,#f59e0b 0%,#d97706 100%);padding:40px 40px 30px;text-align:center;"><img src="https://ellosuit-connect-vista.lovable.app/images/ellosuit-logo.png" alt="Ellosuit" width="180" style="display:inline-block;max-width:180px;height:auto;filter:brightness(0) invert(1);"></td></tr><tr><td style="padding:40px;"><h1 style="color:#1a1a1a;font-size:28px;margin:0 0 16px;text-align:center;">Seu Teste Esta Acabando</h1><p style="color:#4a4a4a;font-size:16px;line-height:1.7;margin:0 0 20px;">Ola <strong>{{nome_cliente}}</strong>,</p><p style="color:#4a4a4a;font-size:16px;line-height:1.7;margin:0 0 20px;">Seu periodo de teste do plano <strong>{{nome_plano}}</strong> termina em breve. Para continuar aproveitando todos os recursos, assine agora e nao perca nada!</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#fffbeb;border:1px solid #fde68a;border-radius:8px;margin:24px 0;"><tr><td style="padding:24px;text-align:center;"><p style="color:#92400e;font-size:16px;font-weight:600;margin:0;">Valor a partir de</p><p style="color:#d97706;font-size:32px;font-weight:700;margin:8px 0;">R$ 297,00/mes</p><p style="color:#92400e;font-size:14px;margin:0;">ou R$ 2.497,00/ano (economize 30%)</p></td></tr></table><p style="text-align:center;margin:32px 0;"><a href="https://www.ellosuit.online/dashboard/assinatura" style="display:inline-block;background:linear-gradient(135deg,#f59e0b,#d97706);color:#ffffff;text-decoration:none;padding:16px 40px;border-radius:8px;font-size:16px;font-weight:600;">Assinar Agora</a></p></td></tr><tr><td style="background-color:#f9f9f9;padding:24px 40px;text-align:center;border-top:1px solid #eee;"><p style="color:#888;font-size:12px;margin:0;">2025 Ellosuit. Todos os direitos reservados.</p></td></tr></table></td></tr></table></body></html>',
true, 'c63ba931-0c34-4461-ae8d-2908aed7dd20', '60008c43-e536-482d-a090-91904de57534');

-- Create Account Suspended template
INSERT INTO public.email_templates (id, name, description, category, html_content, is_active, user_id, company_id) VALUES
('a1b2c3d4-0003-4000-8000-000000000003', 'Conta Suspensa', 'Email quando conta e suspensa por falta de pagamento', 'financeiro',
'<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#f4f4f4;font-family:Arial,Helvetica,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f4f4;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.08);"><tr><td style="background:linear-gradient(135deg,#7f1d1d 0%,#991b1b 100%);padding:40px 40px 30px;text-align:center;"><img src="https://ellosuit-connect-vista.lovable.app/images/ellosuit-logo.png" alt="Ellosuit" width="180" style="display:inline-block;max-width:180px;height:auto;filter:brightness(0) invert(1);"></td></tr><tr><td style="padding:40px;"><h1 style="color:#1a1a1a;font-size:28px;margin:0 0 16px;text-align:center;">Sua Conta Foi Suspensa</h1><p style="color:#4a4a4a;font-size:16px;line-height:1.7;margin:0 0 20px;">Ola <strong>{{nome_cliente}}</strong>,</p><p style="color:#4a4a4a;font-size:16px;line-height:1.7;margin:0 0 20px;">Infelizmente, sua conta foi suspensa devido a falta de pagamento. Para reativar seu acesso e recuperar todos os seus dados, regularize sua situacao.</p><p style="text-align:center;margin:32px 0;"><a href="https://www.ellosuit.online/dashboard/assinatura" style="display:inline-block;background:linear-gradient(135deg,#dc2626,#ef4444);color:#ffffff;text-decoration:none;padding:16px 40px;border-radius:8px;font-size:16px;font-weight:600;">Reativar Minha Conta</a></p><p style="color:#888;font-size:13px;line-height:1.6;margin:20px 0 0;">Seus dados serao mantidos por 30 dias. Apos esse periodo, poderao ser removidos permanentemente.</p></td></tr><tr><td style="background-color:#f9f9f9;padding:24px 40px;text-align:center;border-top:1px solid #eee;"><p style="color:#888;font-size:12px;margin:0;">2025 Ellosuit. Todos os direitos reservados.</p></td></tr></table></td></tr></table></body></html>',
true, 'c63ba931-0c34-4461-ae8d-2908aed7dd20', '60008c43-e536-482d-a090-91904de57534');

